// Bandeja de la Ama — arma el archivo .md que se commitea al repo.
//
// SEGURIDAD: el repo es PUBLICO y este flujo escribe en el. Sin este filtro,
// cualquiera que encuentre el bot puede commitear. AUTORIZADO debe ser el id
// numerico de Telegram de la Ama; mientras valga 0 el flujo no escribe nada.
const AUTORIZADO = 0;   // <-- REEMPLAZAR por el id de la Ama (lo da @userinfobot)

const salida = [];
for (const item of $input.all()) {
  const m = (item.json.message || item.json.channel_post || {});
  const from = m.from || {};
  const texto = (m.text || m.caption || '').trim();

  if (!AUTORIZADO || Number(from.id) !== Number(AUTORIZADO)) continue;
  if (!texto) continue;

  // Hora de Chile. n8n corre en UTC dentro del contenedor: sin esto el sello
  // del archivo queda 4 horas adelantado y el orden de la bandeja miente.
  const d = new Date(((m.date || 0) * 1000) - (4 * 60 * 60 * 1000));
  const p = (n) => String(n).padStart(2, '0');
  const sello = `${d.getUTCFullYear()}-${p(d.getUTCMonth() + 1)}-${p(d.getUTCDate())}` +
                `_${p(d.getUTCHours())}${p(d.getUTCMinutes())}`;

  const slug = texto.toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40) || 'mensaje';

  const nombre = `${sello}_${slug}.md`;
  const iso = new Date((m.date || 0) * 1000).toISOString();

  const contenido =
    '---\n' +
    'origen: telegram\n' +
    `de: ${(from.first_name || 'Ama')}${from.username ? ' (@' + from.username + ')' : ''}\n` +
    `chat_id: ${m.chat ? m.chat.id : from.id}\n` +
    `message_id: ${m.message_id || ''}\n` +
    `fecha: ${iso}\n` +
    'estado: pendiente\n' +
    '---\n\n' +
    texto + '\n';

  salida.push({ json: {
    ruta: `00_Ele/bandeja/${nombre}`,
    nombre,
    contenido,
    commit: `Ama: mensaje por Telegram (${sello})`,
    chat_id: m.chat ? m.chat.id : from.id,
  }});
}
return salida;
